const items = $input.all();

let totalMontoDia = 0;
let totalSolicitudesDia = 0;
let aprobadasCount = 0;
let desgloseText = "";

for (const item of items) {
  const ruta = item.json.ruta;
  const cantidad = item.json.count_id_solicitud || 0;
  const montoRuta = item.json.sum_monto || 0;

  totalSolicitudesDia += cantidad;
  totalMontoDia += montoRuta;

  if (ruta === "APROBACION") {
    aprobadasCount = cantidad;
  }

  desgloseText += `• ${ruta}: ${cantidad} solicitudes | Monto: $${montoRuta.toLocaleString('es-CL')}\n`;
}

let tasaAprobacion = 0;
if (totalSolicitudesDia > 0) {
  tasaAprobacion = ((aprobadasCount / totalSolicitudesDia) * 100).toFixed(2);
}

const mensajeConsolidado = `
 REPORTE CONSOLIDADO DIARIO DE DEVOLUCIONES

FECHA: ${new Date().toLocaleDateString('es-CL')}

DETALLE POR RUTA:
${desgloseText}
RESUMEN GENERAL:
• Monto Total del Día: $${totalMontoDia.toLocaleString('es-CL')}
• Total Solicitudes Procesadas: ${totalSolicitudesDia}
• Tasa de Aprobación Automática: ${tasaAprobacion}%

`.trim();

return [{ json: { mensajeConsolidado, totalMontoDia, totalSolicitudesDia, tasaAprobacion } }];
